issues.reproduce:
Needs a Docker Build Cloud subscription and a builder the account may use.

provider "docker" {
  registry_auth {
    address  = "docker.io"
    username = var.hub_user
    password = var.hub_pat
  }
}
resource "docker_buildx_builder" "cloud" {
  name     = "cloud-builder"
  driver   = "cloud"
  endpoint = "<org>/<builder>"
}

TF_ACC=1 TF_ACC_BUILD_CLOUD=1 TF_ACC_BUILD_CLOUD_BUILDER=<org>/<builder> DOCKER_REGISTRY_USER=<hub user> DOCKER_REGISTRY_PASS=<hub PAT> go test -run TestAccBuildxBuilderCloud_live ./internal/provider -count=1

Daemon with "insecure-registries": ["reg.lan:5000"] and a plain-HTTP registry at reg.lan:5000 holding app:1.

data "docker_registry_image" "x" {
  name = "reg.lan:5000/app:1"
}
output "cfg" { value = data.docker_registry_image.x.config }

terraform apply: warning 'Image config not read from registry', cfg = null; digest and platforms are set.
